const view=shallowRef(null),checking=ref(false),error=ref(''),targetKey=ref('occupied_physical_bed_census'),recipeKey=ref('weekday_mean_4w'),missingPage=ref(1),pairPage=ref(1),capacityPage=ref(1),segmentPage=ref(1),segmentDay=shallowRef(null);let epoch=0,alive=true,paused=false,blocked=null;
