const count=v=>v===null||v===undefined?'未知（null）':String(v),statusLabel=v=>v==='complete'?'原资料完整':'原资料未知',summaryLabels={all_targets_complete:'五目标均完整',partial_targets:'部分目标完整',no_complete_targets:'无完整目标'},recipeLabels={weekday_mean_4w:'主方法：四周同星期均值',seasonal_naive_7d:'基线：七日季节朴素',rolling_mean_7d:'基线：七日滚动均值',rolling_mean_28d:'基线：二十八日滚动均值'};
